from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="260" fill="#e8f4fb"/><rect y="200" width="720" height="60" fill="#8fc77a"/>'
for x,sx,sy,sw,label in [(120,70,80,110,"Morning: Sun low in the East, long shadow to the West"),(360,360,40,26,"Noon: Sun overhead, short shadow"),(600,650,80,110,"Evening: Sun low in the West, long shadow to the East")]:
    b+=f'<circle cx="{sx}" cy="{sy}" r="22" fill="#f6b73c"/><rect x="{x-5}" y="160" width="10" height="40" fill="#6b4a2f"/><circle cx="{x}" cy="150" r="14" fill="#f1c9a5"/>'
    d= sw if x<300 else (-sw if x>500 else 0)
    if x<300: b+=f'<rect x="{x}" y="196" width="{sw}" height="8" fill="#444" opacity=".5"/>'
    elif x>500: b+=f'<rect x="{x-sw}" y="196" width="{sw}" height="8" fill="#444" opacity=".5"/>'
    else: b+=f'<rect x="{x-13}" y="196" width="26" height="8" fill="#444" opacity=".5"/>'
b+='<text x="20" y="235" font-size="13">Morning: low Sun, long shadow</text><text x="300" y="235" font-size="13">Noon: Sun overhead, short shadow</text><text x="520" y="235" font-size="13">Evening: low Sun, long shadow</text><text x="20" y="20" font-size="14">East</text><text x="670" y="20" font-size="14">West</text>'
svgfile('c4evs-sky-shadows.svg',720,260,b)
chapter(4,'evs','our-sky','Our Sky',
 ('Looking up','Have you ever looked up at the sky and noticed that it never looks the same? In the morning it can be orange, at noon the sunlight is strong and at night the Moon and stars appear. In this chapter you will watch the Sun on its journey, find out why shadows change, learn how the Moon changes shape, and see how festivals follow the Moon.'),
 [('The changing sky',['The sky looks different at different times of the day. Its colour changes in the morning, the afternoon and the night, and the Sun\'s colour seems to change too.','The size and shape of the Moon also seem to change over time.','The activities of birds, animals, trees and people change during the day as well.','In the morning the sky can look orange and the Sun looks orange. In the afternoon the sunlight is strong. At night we can see the Moon and stars.','You can draw three pictures of the sky, morning, afternoon and night, and write a table of what you notice in each.']),
  ('The Sun',['The brightest object in the sky is the Sun. It is so bright that other stars cannot be seen when the Sun is in the sky.','The Sun gives us light and heat.','The Sun appears to rise in the morning, move up until it is overhead, and then slowly go down on the other side until it disappears.','We all enjoy this visible journey of the Sun across the sky.','At sunrise the sky is bright and orange, birds start to chirp and fly out, people wake up and the day begins at home.','At sunset the sky turns red and orange, birds return to their nests, and at home we switch on lights and the day winds down.']),
  ('Shadows',['A shadow forms when an object blocks light. Your shadow moves along with you, and if you make different poses its shape changes.','Shadows in the morning are long, shadows at noon are short, and shadows in the evening are long again.','Evening shadows point in the opposite direction to morning shadows.','Shadows form only when something stops light, so they need a source of light like the Sun or a torch.']),
  ('Try it with a torch and a stick',['Take a torch and a stick and make the room dark. Hold the stick in one place and shine the torch on it.','If the stick is close to the torch, the shadow is bigger. If you move it away, the shadow becomes smaller.','If you change the direction of the torch, the direction of the shadow changes too.','This explains the Sun: as the Sun appears to move across the sky, the direction and length of shadows change.']),
  ('Why shadows change',['The Sun appears to move from the East in the morning to overhead at noon and then towards the West in the afternoon.','When the Sun is low in the East, the shadow falls long towards the West. At noon, with the Sun overhead, the shadow is short.','In the evening the Sun is low in the West, so the shadow falls long towards the East.','So the direction of a shadow changes because of the apparent movement of the Sun.']),
  ('Telling time by shadows',['Ancient people noticed that shadows change through the day and made a device called a sundial to tell the time.','Raja Jai Singh of Jaipur built Jantar Mantar in Jaipur, Ujjain, Delhi, Varanasi and Mathura.','It has a huge sundial called Samrat Yantra, which can tell the time accurately from the shadow.','Shadow puppetry has been practised in India for a long time, and you can play with shadows by making animal shapes with your hands.']),
  ('The night sky',['After sunset the sky is full of thousands of twinkling stars, and we can see patterns of stars in the night sky.','Some patterns have names, like Saptarshi, the Seven Sages, but any pattern you see is worth drawing.','The Moon appears to be the biggest object in the night sky and has always fascinated people.','Sky watching is a good habit: look at the sky at the same time every night and keep notes.']),
  ('The Moon and festivals',['The Moon looks different on different nights. On some nights it is a complete circle, called Poornima or the full Moon.','On other nights it looks like the letter C, or as if it has been cut in half. On some nights it is not visible at all, which is called Amavasya or the new Moon.','This cycle repeats, so people in ancient cultures used the shape of the Moon to count days, and this gave rise to the earliest calendars.','Diwali is celebrated when there is no Moon in the sky. Rakshabandhan, Guru Poornima and Buddha Poornima are celebrated when the full Moon is visible.','Eid is celebrated on the first night the Moon is seen after the new Moon. Pongal, Chhath Puja and Karva Chauth are other festivals linked to the Sun or the Moon.','On 23 August 2023 India\'s Vikram Lander landed successfully on the Moon as part of the Chandrayaan mission and collected data about the Moon\'s surface.'])],
 [('Where will your shadow fall in the morning, if the Sun is in the East?',[('In the morning the Sun is low in the East.','The Sun is on the East side.'),('A shadow falls on the side opposite to the Sun.','The object blocks the light from the Sun.'),('So the shadow falls towards the West.','In the evening the Sun is in the West and the shadow falls to the East.')]),
  ('Why is your shadow shorter at noon than in the morning?',[('At noon the Sun is high overhead.','The light comes almost from above.'),('When light comes from above, the shadow falls close under the object.','So the shadow is short.'),('In the morning the Sun is low and the shadow stretches far.','So noon shadows are the shortest.')])],
 ('Explain how the Sun appears to move and how that changes shadows during the day.',['Sun rises in the East, overhead at noon, sets in the West','Morning shadow is long and points West','Noon shadow is short','Evening shadow is long and points East'],['The Sun does not move at all','Shadows are longest at noon','Shadows point towards the Sun']),
 ['The Sun is the brightest object in the sky and gives light and heat.','Shadows are long in the morning and evening and short at noon.','The direction of a shadow changes as the Sun appears to move from East to West.','The Moon changes shape in a cycle, and people used it to make calendars.','Many festivals follow the Sun or the Moon.'],
 [M('1',1,'What is the brightest object in the sky?','The Sun',[('The Moon','The Moon is bright only at night'),('A star','Stars cannot be seen when the Sun is up')],'The Sun is so bright that stars cannot be seen in the day.'),
  M('2',1,'When are shadows the shortest?','At noon',[('In the morning','Shadows are long in the morning'),('In the evening','Shadows are long in the evening')],'At noon the Sun is overhead.'),
  M('3',1,'Where does the Sun appear to rise?','In the East',[('In the West','That is where it sets'),('In the North','It rises in the East')],'The Sun appears to rise in the East and set in the West.'),
  M('4',1,'Which tool tells time by shadows?','A sundial',[('A calendar','A calendar counts days'),('A compass','A compass shows directions')],'A sundial uses the shadow.'),
  M('5',2,'What is the full Moon called?','Poornima',[('Amavasya','That is the new Moon'),('Ekadashi','Not the full Moon')],'Poornima is the full Moon night.'),
  M('6',2,'On which night is the Moon not visible at all?','Amavasya',[('Poornima','Moon is full'),('Eid','A festival')],'Amavasya is the new Moon.'),
  M('7',2,'Which festival is celebrated when there is no Moon in the sky?','Diwali',[('Buddha Poornima','Full Moon'),('Rakshabandhan','Full Moon')],'Diwali is on Amavasya.'),
  M('8',2,'If you move the stick closer to the torch, the shadow becomes ___.','bigger',[('smaller','Closer means bigger'),('colourful','Colour does not change')],'A nearer object makes a larger shadow.'),
  M('9',2,'In the evening, your shadow falls towards the ___.','East',[('West','That is the morning shadow'),('North','Not the direction')],'The Sun is in the West, so the shadow points East.'),
  M('10',2,'What is Samrat Yantra?','A huge sundial at Jantar Mantar',[('A telescope','It is a sundial'),('A calendar','It is a sundial')],'It tells time from shadows.'),
  F('11',2,'Shadows form because an object blocks light.',True,'Light cannot pass through the object.'),
  F('12',3,'Shadows point towards the Sun.',False,'Shadows fall on the side opposite to the Sun.')],
 svgs=[('c4evs-sky-shadows','Three scenes show a child with a long shadow in the morning, a short shadow at noon and a long shadow in the evening.','Shadow length and direction change as the Sun appears to move across the sky.')],
 keep=['shadow','sundial'])
